2	
3	import static org.assertj.core.api.Assertions.assertThat;
4	
5	import java.util.ArrayList;
6	import java.util.List;
7	import java.util.UUID;
8	import java.util.concurrent.Callable;
9	import java.util.concurrent.CountDownLatch;
10	import java.util.concurrent.ExecutorService;
11	import java.util.concurrent.Executors;
12	import java.util.concurrent.Future;
13	import java.util.concurrent.TimeUnit;
14	
15	import com.example.starter.incident.dto.Requests.ReportRequest;
16	import com.example.starter.incident.dto.Requests.StatusRequest;
17	import com.example.starter.incident.dto.Requests.TakeoverRequest;
18	import com.example.starter.incident.dto.Requests.TaskActionRequest;
19	import com.example.starter.incident.dto.Requests.TaskCreateRequest;
20	import com.example.starter.incident.dto.Responses.IncidentView;
21	import com.example.starter.incident.dto.Responses.TaskView;
22	import org.junit.jupiter.api.BeforeEach;
23	import org.junit.jupiter.api.Test;
24	import org.springframework.beans.factory.annotation.Autowired;
25	import org.springframework.boot.test.context.SpringBootTest;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.jdbc.core.JdbcTemplate;
28	
29	/**
30	 * 处置任务并发边界测试：验证依赖图全局锁下并发反向依赖不成环、
31	 * 任务完成与目标事件遏制/当前事件解决按事务提交顺序形成合法结果、
32	 * 同 commandKey 并发单次生效及每事件 20 个任务上限的并发兜底。
33	 */
34	@SpringBootTest
35	class IncidentTaskConcurrencyTest {
36	
37	    @Autowired
38	    private IncidentService service;
39	
40	    @Autowired
41	    private JdbcTemplate jdbc;
42	
43	    @BeforeEach
44	    void clean() {
45	        jdbc.update("DELETE FROM command_keys");
46	        jdbc.update("DELETE FROM incident_status_history");
47	        jdbc.update("DELETE FROM incident_transfers");
48	        jdbc.update("DELETE FROM incident_actions");
49	        jdbc.update("DELETE FROM incident_task_blockers");
50	        jdbc.update("DELETE FROM incident_tasks");
51	        jdbc.update("DELETE FROM incidents");
52	    }
53	
54	    private static String key() {
55	        return "CMD-" + UUID.randomUUID();
56	    }
57	
58	    private void commanding(String incidentKey, String commander) {
59	        service.report(new ReportRequest(incidentKey, "S2", "并发场景", "reporter-1"));
60	        service.takeover(incidentKey, commander, new TakeoverRequest(key()));
61	    }
62	
63	    /**
64	     * 并发提交一批任务并收集结果（成功值或异常）。
65	     */
66	    private static <T> List<Object> runConcurrently(List<Callable<T>> tasks) throws Exception {
67	        ExecutorService pool = Executors.newFixedThreadPool(tasks.size());
68	        try {
69	            CountDownLatch ready = new CountDownLatch(tasks.size());
70	            CountDownLatch start = new CountDownLatch(1);
71	            List<Future<Object>> futures = new ArrayList<>();
72	            for (Callable<T> task : tasks) {
73	                futures.add(pool.submit(() -> {
74	                    ready.countDown();
75	                    start.await(5, TimeUnit.SECONDS);
76	                    try {
77	                        return task.call();
78	                    } catch (Exception e) {
79	                        return e;
80	                    }
81	                }));
82	            }
83	            assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
84	            start.countDown();
85	            List<Object> results = new ArrayList<>();
86	            for (Future<Object> future : futures) {
87	                results.add(future.get(30, TimeUnit.SECONDS));
88	            }
89	            return results;
90	        } finally {
91	            pool.shutdownNow();
92	        }
93	    }
94	
95	    private static long countConflicts(List<Object> results) {
96	        return results.stream().filter(ApiException.class::isInstance)
97	                .map(ApiException.class::cast)
98	                .filter(e -> e.status() == HttpStatus.CONFLICT).count();
99	    }
100	
101	    @Test
102	    void concurrentReverseDependencies_noCycle() throws Exception {
103	        commanding("INC-A", "alice");
104	        commanding("INC-B", "bob");
105	        // 并发创建 A→B 与 B→A 反向依赖：环检测与写入串行一致，恰好一个成功
106	        List<Object> results = runConcurrently(List.of(
107	                () -> service.createTask("INC-A", "alice",
108	                        new TaskCreateRequest(key(), "T-1", "G", "t", List.of("INC-B"))),
109	                () -> service.createTask("INC-B", "bob",
110	                        new TaskCreateRequest(key(), "T-1", "G", "t", List.of("INC-A")))));
111	
