@Transactional
public MergeView merge(String actor, MergeRequest req) {
    String commandKey = requireText(req.commandKey(), "commandKey");
    String mergeKey = requireText(req.mergeKey(), "mergeKey");
    String survivingKey = requireText(req.survivingIncidentKey(), "survivingIncidentKey");
    String mergedKey = requireText(req.mergedIncidentKey(), "mergedIncidentKey");
    if (req.survivingExpectedVersion() == null) throw badRequest("survivingExpectedVersion 不能为空");
    if (req.mergedExpectedVersion() == null) throw ...;
    if (survivingKey.equals(mergedKey)) throw conflict("存续事件与被并入事件必须不同");
    // 确定性顺序锁定双方事件行，避免并发合并死锁
    Incident first = lockIncident(...smaller key...);
    Incident second = lockIncident(...larger key...);
    Incident surviving = survivingKey 对应的; Incident merged = ...;
    return runIdempotent(commandKey, "merge",
            hash(mergeKey, survivingKey, mergedKey, actor,
                 survivingExpectedVersion.toString(), mergedExpectedVersion.toString()),
            MergeView.class, () -> {
                if (merges.findByMergeKey(mergeKey).isPresent()) {
                    throw conflict("mergeKey 已存在: " + mergeKey);
                }
                // 状态门禁：均未进入 RESOLVED/CLOSED/MERGED
                for (Incident i : List.of(surviving, merged)) {
                    if (i.status() == RESOLVED || CLOSED || MERGED) throw conflict(...);
                }
                // 当前指挥人为同一人且为操作者
                if (surviving.commander() == null || !surviving.commander().equals(merged.commander()))
                    throw conflict("双方当前指挥人必须相同");
                requireCommander(surviving, actor);
                // 版本校验
                if (surviving.version() != req.survivingExpectedVersion()) throw conflict(...);
                if (merged.version() != req.mergedExpectedVersion()) throw conflict(...);
                // 任务键冲突
                Set<String> survivingKeys = tasks.listByIncident(surviving.id()).map(taskKey) set;
                List<IncidentTask> mergedTasks = tasks.listByIncident(merged.id());
                List<String> conflicts = mergedTasks.stream().map(taskKey).filter(survivingKeys::contains).sorted().toList();
                if (!conflicts.isEmpty()) throw conflict("任务键冲突", conflicts);
                // 图锁
                tasks.lockGraph();
                // 迁移任务
                tasks.reassignTasks(merged.id(), surviving.id(), now);
                // 改挂指向被并入事件的边
                for (BlockerRow row : tasks.listBlockersPointingTo(merged.id())) {
                    IncidentTask owner = tasks.findById(row.taskId()).orElseThrow();
                    if (owner.incidentId() == surviving.id() || tasks.existsBlocker(row.taskId(), surviving.id())) {
                        tasks.deleteBlocker(row.id());
                    } else {
                        tasks.updateBlockerTarget(row.id(), surviving.id());
                    }
                }
                // 丢弃指向自身的边（含迁移后任务原本指向存续事件的边）
                for (long selfId : tasks.listSelfBlockerRowIds()) tasks.deleteBlocker(selfId);
                // 整图环检测
                if (tasks.hasCycle()) throw conflict("合并后依赖图成环，已回滚");
                // 作废待处理升级（期限在 markMerged 内置空）
                escalations.cancelOpenForIncident(merged.id(), now);
                // 状态与版本
                incidents.markMerged(merged.id(), surviving.id(), now);
                incidents.bumpVersion(surviving.id(), now);
                incidents.insertStatusChange(new StatusChange(0L, merged.id(), merged.status(), MERGED, actor, now));
                // 不可变合并记录
                try {
                    merges.insert(new IncidentMerge(0L, mergeKey, surviving.id(), merged.id(), actor, now));
                } catch (DuplicateKeyException e) {
                    throw conflict("mergeKey 已存在: " + mergeKey);
                }
                List<String> movedTaskKeys = mergedTasks.stream().map(taskKey).sorted().toList();
                return new MergeView(mergeKey, survivingKey, mergedKey,
                        surviving.version() + 1, merged.version() + 1, movedTaskKeys, actor, now);
            });
}
