        // RESOLVED 的被并入事件 → 409
        service.changeStatus("INC-M", "alice", new StatusRequest(key(), "CONTAINED"));
        service.changeStatus("INC-M", "alice", new StatusRequest(key(), "RESOLVED"));
        assertApiStatus(() -> merge("alice", "INC-S", "INC-M", 0L, 1L), HttpStatus.CONFLICT);
