        service.changeStatus("INC-S2", "alice", new StatusRequest(key(), "CLOSED"));
        commanding("INC-M2", "alice");
        assertApiStatus(() -> merge("alice", "INC-S2", "INC-M2", 3L, 0L), HttpStatus.CONFLICT);
