    // 全库不再存在指向自身的边
    Integer selfEdges = jdbc.queryForObject(
            "SELECT COUNT(*) FROM incident_task_blockers b"
                    + " JOIN incident_tasks t ON t.id = b.task_id"
                    + " WHERE t.incident_id = b.blocker_incident_id", Integer.class);
